const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

const groupFor = (name: string) => {
  const n = name.toLowerCase();
  if (n.includes("qa") || n.includes("quality assurance")) return "Quality Assurance";
  if (n.includes("sales") || n.includes("presales")) return "Sales";
  if (n.includes("hr")) return "HR";
  if (n.includes("architecture") || n.includes("system design") || n.includes("microservices")) return "Architecture";
  return "Technology";
};

async function main() {
  const categoryCache = new Map<string, { id: string; subcategoryId: string }>();
  const categoryCounts = new Map<string, number>();
  for (const row of topics) categoryCounts.set(row[0], (categoryCounts.get(row[0]) ?? 0) + 1);

  for (let index = 0; index < topics.length; index += 1) {
    const [categoryName, question, slug, shortDescription, sampleAnswer] = topics[index];
    const categorySlug = slugify(categoryName);
    let categoryInfo = categoryCache.get(categorySlug);
    if (!categoryInfo) {
      const category = await prisma.category.upsert({
        where: { slug: categorySlug },
        update: { name: categoryName, group: groupFor(categoryName) },
        create: { name: categoryName, slug: categorySlug, group: groupFor(categoryName), description: `${categoryName} interview questions.` },
      });
      const subcategory = await prisma.subcategory.upsert({
        where: { categoryId_slug: { categoryId: category.id, slug: categorySlug } },
        update: { name: categoryName },
        create: { name: categoryName, slug: categorySlug, categoryId: category.id },
      });
      categoryInfo = { id: category.id, subcategoryId: subcategory.id };
      categoryCache.set(categorySlug, categoryInfo);
    }
    const position = index % Math.max(categoryCounts.get(categoryName) ?? 1, 1);
    const experienceLevel = position < 40 ? ExperienceLevel.FRESHER : position < 120 ? ExperienceLevel.MID_LEVEL : ExperienceLevel.EXPERIENCED;
    const difficulty = position < 40 ? Difficulty.EASY : position < 120 ? Difficulty.MEDIUM : Difficulty.HARD;
    const n = categoryName.toLowerCase();
    const interviewType = n.includes('hr') ? InterviewType.HR : (n.includes('sales') || n.includes('presales')) ? InterviewType.BEHAVIORAL : InterviewType.TECHNICAL;
    await prisma.interviewQuestion.upsert({
      where: { slug },
      update: { question, categoryId: categoryInfo.id, subcategoryId: categoryInfo.subcategoryId, experienceLevel, difficulty, interviewType, shortDescription, explanation: `Interview preparation answer for ${question}`, sampleAnswer, detailedAnswer: sampleAnswer, keyPoints: [], commonMistakes: [], followUpQuestions: [], tags: [categoryName], isPublished: true },
      create: { question, slug, categoryId: categoryInfo.id, subcategoryId: categoryInfo.subcategoryId, experienceLevel, difficulty, interviewType, shortDescription, explanation: `Interview preparation answer for ${question}`, sampleAnswer, detailedAnswer: sampleAnswer, keyPoints: [], commonMistakes: [], followUpQuestions: [], tags: [categoryName], isPublished: true },
    });
  }
  console.log(`SUCCESS: processed ${topics.length} questions from ${categoryCounts.size} categories.`);
}

main().catch((error) => { console.error("ERROR: consolidated seed failed:", error); process.exit(1); }).finally(() => prisma.$disconnect());
